// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 fuzzBlockNumber, uint256 fuzzTimestamp) public {
        vm.assume(fuzzTimestamp > 0);
        vm.assume(fuzzTimestamp > c.pastBlockTime());
        vm.roll(fuzzBlockNumber);
        vm.warp(fuzzTimestamp);

        address caller = address(0x1234);
        vm.deal(caller, 10 ether);
        vm.prank(caller);
        (bool success, ) = address(c).call{value: 10 ether}("");
        require(success, "fallback call failed");

        bool shouldBeZero = (fuzzBlockNumber % 15 == 0);
        uint256 bal = address(c).balance;
        if (shouldBeZero) {
            assertTrue(bal == 0);
        } else {
            assertTrue(bal > 0);
        }
    }
}
